INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-08-03' FROM countries WHERE name_en = 'South Korea';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'en', 'Post-issuance real-time reporting — the National Tax Service (NTS) e-Tax Invoice system', 'This deep-dive page reflects publicly available National Tax Service guidance and industry reporting as of August 2026 and is provided for general awareness, not legal or tax advice. The individual-entrepreneur threshold has been reduced repeatedly and further reductions are widely expected — confirm the current figure directly with the NTS or your tax adviser before relying on any specific number.', 'South Korea''s e-Tax Invoice system is the most mature mandate in this tracker: mandatory for all corporations since January 2011, then extended to individual entrepreneurs via a revenue threshold that has fallen in stages ever since — KRW 1 billion (2012) → 300 million (2014) → 200 million (2022) → 100 million (2023, alongside the introduction of self-billing invoices) → 80 million (2024), the lowest yet.', 'e-Tax Invoices are created in XML format with a digital signature — either a Public Certification Authority certificate or an NTS-issued e-tax certificate — and transmitted to the NTS Central Platform (Hometax).', 'Unlike the clearance-model mandates common elsewhere in this tracker, South Korea operates a post-issuance real-time-reporting model: the invoice is legally valid once delivered to the buyer, and next-day transmission to the NTS is a separate reporting duty rather than a precondition for validity. The mandate covers domestic B2B and B2G transactions; there is no general B2C e-invoicing requirement.', 'Getting compliant means confirming whether you''re in scope (all corporations, or individual entrepreneurs above the current KRW 80 million threshold), obtaining a digital certificate, choosing a submission channel, and meeting the next-day transmission deadline.', 'South Korea backs the mandate with a graduated, percentage-of-supply-value penalty schedule for corporations and in-scope individual entrepreneurs, capped annually except for intentional violations — and, separately, missing or incorrect supplier invoices cause the buyer to lose their own input-VAT deduction rights.', 'South Korea''s e-Tax Invoice system has required electronic VAT invoicing and next-day NTS reporting for all corporations since January 2011 — the longest-running mandate covered anywhere in this tracker. Individual entrepreneurs have been phased in through a steadily falling revenue threshold, now KRW 80 million as of July 2024, the lowest level yet. Penalties are graduated by violation type (2% of supply value for non-issuance, down to 0.3-0.5% for delayed transmission) and separately, non-compliant invoices cost the buyer their own VAT deduction.', '🇰🇷' FROM countries WHERE name_en = 'South Korea';
