INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'South Korea';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & standard', '[["Invoice format", "XML, with a digital signature"], ["Digital signature options", "Public Certification Authority certificate, or an NTS-issued e-tax certificate"], ["Transmission platform", "NTS Central Platform (Hometax)"], ["Legal basis", "Value-Added Tax Act, administered by the National Tax Service"]]', 'The XML-plus-digital-signature pattern has been stable for over a decade, so most accounting and ERP systems already support it natively — the real integration decision is which of the five submission channels to use.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'South Korea';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Identifiers & registration', '[["Taxpayer identity", "Korean business registration number"], ["Submission channels", "Free NTS Hometax portal, a certified ASP, an in-house accounting system with a digital certificate, the AVRS telephone system, or in-person at a tax office"], ["Registration/reporting platform", "hometax.go.kr"], ["Authority", "National Tax Service (NTS)"]]', 'Five separate channels is more than most mandates in this tracker offer — the AVRS telephone and in-person routes exist specifically for very small taxpayers without any digital infrastructure of their own.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'South Korea';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Mandatory content & archiving', '[["Required fields", "Tax identification number and address of both parties, VAT-inclusive cost, invoice date, customer information"], ["Optional field", "Description of goods is not mandatory"], ["Retention period", "5 years; centralized NTS storage now satisfies this obligation without a separate supplier archive"], ["Self-billing", "Available since July 2023 where a supplier cannot issue an invoice, subject to district tax office confirmation"]]', 'The government''s own centralized storage covering the retention requirement is a genuine convenience most newer mandates in this tracker don''t yet offer — one less thing for a compliant business to manage itself.', NULL);
INSERT INTO deep_dive_lifecycle_cards (country_id, section, sort_order, display_style) SELECT id, 'scope_transmission', 0, 'pills' FROM countries WHERE name_en = 'South Korea';
INSERT INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 'en', 'The issue-then-report flow', 'Every e-Tax Invoice moves through the same sequence — note this is reporting, not clearance:', 'The invoice is already legally valid once it reaches the buyer — the NTS is not asked to approve it first. This is the key difference from the clearance-model mandates covered elsewhere in this tracker.');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 0, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Invoice issued in signed XML');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 1, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Delivered to buyer — legally valid now');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 2, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Transmitted to NTS by next business day');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 3, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Buyer relies on it for input-VAT deduction');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'South Korea';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Who''s in scope, and since when', '[["All corporations", "Mandatory since January 2011, regardless of size"], ["Individual entrepreneurs above KRW 80 million", "Mandatory since July 2024 (the threshold has fallen in stages since 2012)"], ["Individual entrepreneurs below the threshold", "Voluntary participation only"], ["Domestic B2B and B2G transactions", "The mandate''s actual coverage — see the next card for what''s excluded"]]', 'The threshold has fallen five times since 2012 (1 billion → 300 million → 200 million → 100 million → 80 million KRW) — check the current figure directly rather than relying on a number you may have seen a few years ago.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'South Korea';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Domestic B2B and B2G only', '[["B2B", "Covered — the core of the mandate"], ["B2G", "Covered"], ["B2C (consumer retail)", "Not covered by the e-Tax Invoice mandate"], ["Cross-border/export transactions", "Not addressed by this mandate"]]', 'This is a narrower scope than several mandates elsewhere in this tracker that also reach B2C — worth checking against your own transaction mix before assuming full coverage.', NULL);
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'South Korea';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Non-issuance of a required e-Tax Invoice', '2% of the supply value', 'KRW 50 million per year (KRW 100 million for large companies)');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'South Korea';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Issuing a paper invoice where an e-Tax Invoice is required', '1% of the supply value', 'KRW 50 million per year (KRW 100 million for large companies)');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'South Korea';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Failure to transmit to the NTS by the deadline', '1% of the supply value', 'KRW 50 million per year (KRW 100 million for large companies)');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'South Korea';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Delayed issuance or delayed transmission', '0.3%-0.5% of the supply value', 'KRW 50 million per year (KRW 100 million for large companies)');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'South Korea';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🧾 VAT deduction denial — a second, separate consequence', NULL, NULL, 'Beyond the fines above, a missing or incorrect e-Tax Invoice causes the buyer to lose their own input-VAT deduction rights on that transaction. As with several other mandates in this tracker, this gives every VAT-registered buyer a direct financial incentive to police their suppliers'' compliance, not just the tax authority.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'South Korea';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📅 Fifteen years of enforcement, not a new risk', NULL, NULL, 'Unlike most mandates added to this tracker, South Korea''s e-Tax Invoice system is not a recent change to plan for — it has applied to all corporations since 2011. The live compliance question for most businesses today is only whether the current KRW 80 million individual-entrepreneur threshold applies to them, not whether the system itself is new.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'South Korea';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚖️ Fictitious-invoice penalties are tightening in 2026', NULL, NULL, 'Separately from the e-Tax Invoice penalty schedule above, South Korea''s broader VAT penalty regime is getting stricter: the fine for issuing or receiving a fictitious VAT invoice is rising from 3% to 4% of the taxable supply amount shown, part of a wider set of 2026 Korean tax law changes — a reminder that even a mature, settled mandate like this one still generates real regulatory news.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'South Korea';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm whether you''re in scope', 'All corporations have been in scope since 2011 regardless of size; individual entrepreneurs should check their prior-year supply value against the current KRW 80 million threshold, not an older figure.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'South Korea';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Obtain a digital certificate', 'You''ll need either a Public Certification Authority certificate or an NTS-issued e-tax certificate before you can issue a compliant e-Tax Invoice.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'South Korea';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Choose your submission channel', 'Pick from the free NTS Hometax portal, a certified ASP, an in-house accounting system with a digital certificate, the AVRS telephone system, or in-person filing — whichever matches your invoice volume and existing systems.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'South Korea';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Map your invoice content to the required fields', 'Cover both parties'' tax identification numbers and addresses, the VAT-inclusive cost, the invoice date, and customer information — description of goods is optional.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'South Korea';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Meet the next-business-day transmission deadline', 'Transmit to the NTS by the day after issuance where possible; the monthly-summary fallback by the 10th of the following month exists but carries its own penalty risk if relied on routinely.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE name_en = 'South Korea';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Audit incoming invoices before claiming input-VAT deduction', 'A missing or incorrect e-Tax Invoice from a supplier blocks your own deduction, regardless of whether the fault is yours — check before you rely on it.');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://www.hometax.go.kr', 0 FROM countries WHERE name_en = 'South Korea';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'NTS Hometax — e-Tax Invoice system');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://www.nts.go.kr/english/', 1 FROM countries WHERE name_en = 'South Korea';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'National Tax Service (NTS) — English information portal');
